// Characterization tests: pin what clients currently observe, quirks included.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { apple: 3, pear: 2.5, tv: 60 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const call = async (method, path, body, raw) => {
  const res = await fetch(base + path, {
    method,
    headers: body !== undefined || raw !== undefined ? { 'content-type': 'application/json' } : {},
    body: raw ?? (body === undefined ? undefined : JSON.stringify(body)),
  })
  return { status: res.status, type: res.headers.get('content-type'), body: await res.json() }
}

test('POST /orders creates an order and returns 201 with id, items, total', async () => {
  const items = [{ sku: 'apple', qty: 2 }]
  const r = await call('POST', '/orders', { items })
  assert.equal(r.status, 201)
  assert.equal(r.type, 'application/json')
  assert.deepEqual(Object.keys(r.body).sort(), ['id', 'items', 'total'])
  assert.match(r.body.id, /^\d+$/)
  assert.deepEqual(r.body.items, items)
  assert.equal(r.body.total, 6)
})

test('ids are strings and increment per order', async () => {
  const a = await call('POST', '/orders', { items: [{ sku: 'apple', qty: 1 }] })
  const b = await call('POST', '/orders', { items: [{ sku: 'apple', qty: 1 }] })
  assert.equal(typeof a.body.id, 'string')
  assert.equal(Number(b.body.id), Number(a.body.id) + 1)
})

test('total sums all items', async () => {
  const r = await call('POST', '/orders', { items: [{ sku: 'apple', qty: 2 }, { sku: 'tv', qty: 1 }] })
  assert.equal(r.body.total, 66)
})

test('total is floored to a whole number', async () => {
  const r = await call('POST', '/orders', { items: [{ sku: 'pear', qty: 1 }] })
  assert.equal(r.body.total, 2)
})

test('no discount at exactly 100', async () => {
  const r = await call('POST', '/orders', { items: [{ sku: 'apple', qty: 1 }, { sku: 'tv', qty: 1 }, { sku: 'pear', qty: 14 }, { sku: 'apple', qty: 0 }] })
  // 3 + 60 + 35 = 98 -> use an exact 100 below
  assert.equal(r.body.total, 98)
  const exact = await call('POST', '/orders', { items: [{ sku: 'tv', qty: 1 }, { sku: 'pear', qty: 16 }] })
  assert.equal(exact.body.total, 100)
})

test('10% discount when total is over 100, then floored', async () => {
  const r = await call('POST', '/orders', { items: [{ sku: 'tv', qty: 2 }] })
  assert.equal(r.body.total, 108)
  const odd = await call('POST', '/orders', { items: [{ sku: 'apple', qty: 34 }] }) // 102 -> 91.8
  assert.equal(odd.body.total, 91)
})

test('GET /orders/:id returns the stored order', async () => {
  const created = await call('POST', '/orders', { items: [{ sku: 'tv', qty: 1 }] })
  const r = await call('GET', `/orders/${created.body.id}`)
  assert.equal(r.status, 200)
  assert.deepEqual(r.body, created.body)
})

test('GET unknown order returns 200 with { error: "not found" } (not 404)', async () => {
  const r = await call('GET', '/orders/999999')
  assert.equal(r.status, 200)
  assert.deepEqual(r.body, { error: 'not found' })
})

test('POST with missing, empty or non-array items returns 400', async () => {
  for (const body of [{}, { items: [] }, { items: 'apple' }, { items: null }]) {
    const r = await call('POST', '/orders', body)
    assert.equal(r.status, 400)
    assert.deepEqual(r.body, { error: 'items required' })
  }
})

test('POST with malformed JSON returns 400', async () => {
  const r = await call('POST', '/orders', undefined, '{nope')
  assert.equal(r.status, 400)
  assert.deepEqual(r.body, { error: 'items required' })
})

test('POST with empty body returns 400', async () => {
  const r = await call('POST', '/orders')
  assert.equal(r.status, 400)
})

test('unknown sku (no price) yields total null but still 201', async () => {
  const r = await call('POST', '/orders', { items: [{ sku: 'ghost', qty: 1 }] })
  assert.equal(r.status, 201)
  assert.equal(r.body.total, null)
})

test('unknown routes and methods return 404 { error: "no route" }', async () => {
  for (const [m, p] of [['GET', '/'], ['GET', '/orders'], ['DELETE', '/orders/1'], ['PUT', '/orders'], ['GET', '/orders/1/extra']]) {
    const r = await call(m, p)
    assert.equal(r.status, 404, `${m} ${p}`)
    assert.deepEqual(r.body, { error: 'no route' })
  }
})

test('query string is ignored when routing', async () => {
  const created = await call('POST', '/orders?x=1', { items: [{ sku: 'apple', qty: 1 }] })
  assert.equal(created.status, 201)
  const r = await call('GET', `/orders/${created.body.id}?verbose=1`)
  assert.deepEqual(r.body, created.body)
})
